# run west build in verbose mode. For example:
# west -v build -p always -b frdm_kl25z sample_apps/zephyr_ada_hello 2>&1 | tee ~/tmp/tmp.log
#
ZEPHYR_BASE_DIR=~/my-projects/third-party/zephyrproject/zephyr
ZEPHYR_GCC=~/my-projects/third-party/zephyr-sdk/arm-zephyr-eabi/bin/arm-zephyr-eabi-gcc

ZEPHYR_CFLAGS='-DCPU_MKL25Z128VLK4 -DKERNEL -DK_HEAP_MEM_POOL_SIZE=512 -DPICOLIBC_LONG_LONG_PRINTF_SCANF -DZVFS_OPEN_SIZE=4 -D_POSIX_CLOCK_SELECTION=200809L -D_POSIX_CPUTIME=200809L -D_POSIX_C_SOURCE=200809L -D_POSIX_MONOTONIC_CLOCK=200809L -D_POSIX_MULTI_PROCESS=200809L -D_POSIX_REALTIME_SIGNALS=200809L -D_POSIX_THREADS=200809L -D_POSIX_THREAD_SAFE_FUNCTIONS=200809L -D_POSIX_TIMERS=200809L -D__LINUX_ERRNO_EXTENSIONS__ -D__PROGRAM_START -D__ZEPHYR__=1 -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/kernel/include -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/arch/arm/include -I/Users/jgrivera/my-projects/zephyr_ada/build/zephyr/include/generated/zephyr -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/include -I/Users/jgrivera/my-projects/zephyr_ada/build/zephyr/include/generated -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/soc/nxp/kinetis -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/lib/libc/picolibc/include -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/lib/posix/c_lib_ext/getopt -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/include/zephyr/posix -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/soc/nxp/kinetis/kl2x/. -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/soc/nxp/kinetis/common -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/soc/nxp/kinetis/../common -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/cmsis_6/CMSIS/Core/Include -I/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/modules/cmsis_6/. -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/microchip/include -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/nxp/mcux/mcux-sdk/devices/MKL25Z4 -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/nxp/mcux/mcux-sdk/devices/MKL25Z4/drivers -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/nxp/mcux/mcux-sdk-ng/drivers/common -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/nxp/mcux/mcux-sdk/devices/MKL25Z4/. -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/nxp/mcux/mcux-sdk-ng/drivers/lpsci -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/nxp/mcux/mcux-sdk-ng/drivers/port -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/nxp/mcux/mcux-sdk-ng/drivers/rcm -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/nxp/mcux/mcux-sdk-ng/drivers/sim -I/Users/jgrivera/my-projects/third-party/zephyrproject/modules/hal/st/sensor/inc -isystem /Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/lib/libc/common/include -fno-strict-aliasing -Os -imacros /Users/jgrivera/my-projects/zephyr_ada/build/zephyr/include/generated/zephyr/autoconf.h -fno-printf-return-value -fno-common -g -gdwarf-4 -fdiagnostics-color=always -mcpu=cortex-m0plus -mthumb -mabi=aapcs -mfp16-format=ieee -mtp=soft --sysroot=/Users/jgrivera/my-projects/third-party/zephyr-sdk/arm-zephyr-eabi/arm-zephyr-eabi -imacros /Users/jgrivera/my-projects/third-party/zephyrproject/zephyr/include/zephyr/toolchain/zephyr_stdint.h -Wall -Wformat -Wformat-security -Wno-format-zero-length -Wdouble-promotion -Wno-pointer-sign -Wpointer-arith -Wexpansion-to-defined -Wno-unused-but-set-variable -Werror=implicit-int -fno-pic -fno-pie -fno-asynchronous-unwind-tables -ftls-model=local-exec -fno-reorder-functions --param=min-pagesize=0 -fno-defer-pop -fmacro-prefix-map=/Users/jgrivera/my-projects/zephyr_ada/sample_apps/zephyr_ada_hello=CMAKE_SOURCE_DIR -fmacro-prefix-map=/Users/jgrivera/my-projects/third-party/zephyrproject/zephyr=ZEPHYR_BASE -fmacro-prefix-map=/Users/jgrivera/my-projects/third-party/zephyrproject=WEST_TOPDIR -ffunction-sections -fdata-sections -specs=picolibc.specs -std=c17'

output_dir=src/third_party/generated_zephyr_ada_bindings/frdm_kl25z
mkdir -p $output_dir
rm -f  $output_dir/*
cd $output_dir
$ZEPHYR_GCC $ZEPHYR_CFLAGS -c -fdump-ada-spec -C ${ZEPHYR_BASE_DIR}/include/zephyr/kernel.h
$ZEPHYR_GCC $ZEPHYR_CFLAGS -c -fdump-ada-spec -C ${ZEPHYR_BASE_DIR}/include/zephyr/posix/pthread.h
#$ZEPHYR_GCC $ZEPHYR_CFLAGS -c -fdump-ada-spec -C ${ZEPHYR_BASE_DIR}/include/zephyr/portability/cmsis_os2.h
cd -
ls -l $output_dir
